(757, 'Baby Bedside Music Bell', 'BBMB-1650', 'bed-bell-music', '<p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Discription:</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Baby Bed Side Music Bell Set is The Best Gift for the Children Imagination Creation Study Enlighten the baby’s intelligence, the rich color which helps enhance the baby’s cognition to the color Cartooned Hanging Piece can be used as a Ring.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">The Lovely Cartoon models and bright colors attract babies and enhance their interests. Newly-born babies take delight in knowing and exploring the world. Their exploration develops from accidental discoveries into conscious activities. During this period, it helps the development of baby’s sense organs, attracts them and trains their perception and motion. It is the toy which especially avails the development of their seeing and hearing.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Bedside Bell Lovely 100 Wonderful Music Audio Visual development Early Education Developing intelligence Manipulative ability Parent Child interaction.<br>Feature:<br>Material: Plastic<br>100 Lovely Music<br>Audio Visual development<br>Early Education<br>Developing intelligence<br>Manipulative ability<br>Parent Child interaction<br>4 pieces Lovely Toy</p>', '1900', '1650', '63e20b2e67e58.jpg', 'Baby Bed Side Music Bell Toy', 'Bed, Music', 'Discription:\n\nBaby Bed Side Music Bell Set is The Best Gift for the Children Imagination Creation Study Enlighten the baby’s intelligence, the rich color which helps enhance the baby’s cognition to the color Cartooned Hanging Piece can be used as a Ring.', 'Active', '2023-02-07 14:29:14', '2023-02-20 13:47:47'),
(758, 'Baby Vibrating Chair', 'BVC-3300', 'baby-vibrating-chair', '<p><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Vibrating Hu – Baby Chair Our babies will be extremely excited with the shimmering colorful chair, soft cushion, gentle vibration motion to help baby fall asleep easily and soundly.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">There are 2 modes Parents: Standing mode is used when the baby sits and plays or when the mother feeds the baby. Vibration mode will help your baby quickly fall asleep and gradually adapt to independent sleep.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Special: The chair is the perfect place for your baby to lie down and play or bask in the sun every morning as well as have a good night’s sleep right on the chair.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">The design of the seat is sunken to support the lying position – The most comfortable seat for the baby, better protect the baby’s spine.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Strong 3-point safety belt, resized to fit each child’s body size.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Lovely toys with bright colors and funny shapes will stimulate curiosity and exercise baby’s ability to grasp and practice with.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Especially the toy in the middle will play funny music every time the baby pulls.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">The cushion is removable for washing and cleaning, machine washable.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">The weight of the chair is light with the ability to fold easily, convenient for the mother to move the vibrating chair around the house.</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">The product is suitable for babies from birth to 18 kg (about 3-4 years old)</span><br></p>', '4000', '3300', '63e21535355ab.jpg', 'Baby Chair Vibrating', 'Vibrating,Chair, Baby,Baby Chair Vibrating', 'Vibrating Hu – Baby Chair Our babies will be extremely excited with the shimmering colorful chair, soft cushion, gentle vibration motion to help baby fall asleep easily and soundly.\nThere are 2 modes Parents: Standing mode is used when the baby sits and p', 'Active', '2023-02-07 15:11:40', '2023-02-14 17:13:06'),
(759, 'Children Boxing Exercise Toy', 'CBET-650', 'boxing', '<p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Children Boxing Exercise Toy + Pumper Included<br>Baby Care Present Inflatable Pvc hit Me Tiger.<br>Gift your kid this wonderful collection of Inflatable Bop Bags.<br>Kids love to play outdoors and indoors. Make their playtime more exciting with the Intex Hit Me bop bag set.<br>Made of 0.20-mm PVC vinyl material, This animal bop bag set has a water-weighted base that keeps all the bop bags in place when they are hit over and over again. It Helps to Increase your child’s Physical strength And Activity. Your toddlers will love to hit the bop bags as they bounce back and do not fall flat.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">FEATURES :<br>Portable, durable and comfortable.<br>Easy to inflate, deflate and store.<br>Ideal for Children Ages 3 – 8 Years.<br>Weight Capacity: .60 Kg<br>Inflatated Size :- (+/-) 25 x 24 x 29</p>', '800', '650', '63e21a3b85687.jpg', 'Children Boxing Exercise Toy', 'Exercise Toy,Boxing Exercise Toy,Children Boxing, Exercise Toy', 'Children Boxing Exercise Toy + Pumper Included\nBaby Care Present Inflatable Pvc hit Me Tiger.\nGift your kid this wonderful collection of Inflatable Bop Bags.\nKids love to play outdoors and indoors. Make their playtime more exciting with the Intex Hit Me b', 'Active', '2023-02-07 15:31:21', '2023-02-14 17:46:18'),
(760, 'Inflatable Baby Swimming Ring', 'IBSR-300', 'inflatable-baby-swimming-ring', '<p><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Intex Lively Print Swim Ring is made of sturdy, durable vinyl material, this fun swimming accessory brings some extra color and confidence to your child’s pool experience. Recommended for children ages three to ten. Great for swimming pools and the beach, the Intex Swim Ring Tube adds to the fun of water play. This 24″ diameter inflatable tube features a fun and colorful design. Have fun splashing around the pool with the Intex Lively Print Swim Rings. This swim ring is a perfect swim ring for kids who are learning to swim.<br></span><br></p><ul class=\"\" data-spm-anchor-id=\"a2a0e.pdp.product_detail.i1.1ff8ReewReewRQ\" style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li class=\"\" data-spm-anchor-id=\"a2a0e.pdp.product_detail.i0.1ff8ReewReewRQ\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">* Product Type: Inflatable Lively Printed Tire Swimming Ring</li><li class=\"\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">* Item Type: Swimming Ring</li><li class=\"\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">* Brand: INTEX</li><li class=\"\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">* Materials: PVC</li><li class=\"\" style=\"border: 0px; font-family: inherit; font-style: in