(766, 'Infant Support Sofa', 'ISS-950', 'infant-support-sofa', '<p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Infant Baby Support Sofa</strong><br>Plush Cushion Toys Baby Sofa Learn Sitting Chair for Toddler Infant.<br>Support sofa using for baby to learn about sitting.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">High-quality material:&nbsp;</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Short Plush + PP Cotton</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Upright Seating Position:</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Helps Stabilize your Baby’s back, while they learn to sit up.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Lightweight and Portable:</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Size about 40 * 45 cm / 17.72 * 17.72 IN, Easily Provides your baby a Soft Place to Sit in any Room of the House.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Seating support:</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">The Upright Position also Helps Prevent after-meal Reflux.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Fashionable Cute animal Shaped design:</strong></p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Let baby Keep Sitting Posture and Comfortable</p>', '1500', '1000', '63e78b2977240.jpg', 'Infant Support Sofa', 'Sofa,Infant,Support', 'Infant Baby Support Sofa\nPlush Cushion Toys Baby Sofa Learn Sitting Chair for Toddler Infant.\nSupport sofa using for baby to learn about sitting.\n\nHigh-quality material: \n\nShort Plush + PP Cotton\n\nUpright Seating Position:\n\nHelps Stabilize your Baby’s bac', 'Active', '2023-02-11 18:35:41', '2023-02-11 18:35:41'),
(767, 'Portable BBQ Truck', 'BBQ-1000', 'portable-bbq-truck', '<p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Measurement: 22cm x 24.5cm x 10.5cm (Box)</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Be the Barbeque expert with this colorful and melodic sound truck!</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Contains 1 unit of Barbeque Truck with accessories Requires 3x 1.5V AA batteries (not included)</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Suitable for kids age 3 years and above Assorted designs and colors</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Perfect as a gift for young children Design is randomly selected</p><ul style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Suitable for occupational therapy</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Suitable to develop hand-to-eye coordination</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Suitable for developing motor skills</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Suitable for autistic or children with ASD</li></ul>', '1500', '1200', '63e7902a8dc4d.jpg', 'Portable BBQ Truck', 'BBQ', 'Measurement: 22cm x 24.5cm x 10.5cm (Box)\n\nBe the Barbeque expert with this colorful and melodic sound truck!\n\nContains 1 unit of Barbeque Truck with accessories Requires 3x 1.5V AA batteries (not included)\n\nSuitable for kids age 3 years and above Assorte', 'Active', '2023-02-11 18:55:42', '2023-02-11 18:55:42'),
(768, 'Baby Bather Chair', 'BBC-1500', 'baby-bather-chair', '<h3 class=\"product-subtitle\" style=\"border: 0px; font-family: Poppins, sans-serif; font-size: 26px; font-weight: 700; margin-top: 0px; margin-bottom: 15px; outline: 0px; padding: 0px; vertical-align: baseline; clear: both; line-height: 1.3; color: rgb(61, 61, 61);\">Bath sets</h3><div class=\"product-description detail-info-entry\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><p style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">A baby bath chair is a MUST have. Babies love the bath chair. It hugs them in with their soft mesh back support.</p><p style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">They know it’s time for their wash the moment you place them in. Fold the bath chair away when not used – It’s the simple.</p><h2 style=\"border: 0px; font-family: Poppins, sans-serif; font-size: 30px; font-style: inherit; font-weight: 700; margin-top: 0px; margin-bottom: 1em; outline: 0px; padding: 0px; vertical-align: baseline; clear: both; line-height: 1.3; color: rgb(61, 61, 61);\">iBaby Foldable Baby Bath Chair</h2><ul style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial;\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Soft mesh sling conforms to a newborn’s body for extra comfort</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Adjustable backrest has&nbsp;<strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">three recline positions</strong>&nbsp;for convenience</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Solid base provides a stable support for the baby bather</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Machine washable fabric is easy to remove and clean</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Use in sink or tub</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Folds flat for storage</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">For use until baby can sit up unassisted.</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><strong class=\"text-normal greycolor2 overvw_label\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Recommended Age:</strong>&nbsp;Suitable for 0 month-3 years</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><strong class=\"text-normal greycolor2 overvw_label\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Product Dimensions:</strong>&nbsp;33 x 36 x 7.5 cm</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><strong class=\"text-normal greycolor2 overvw_label\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Weight:</strong>&nbsp;1.25KG</li></ul></div>', '2000', '1500', '63e7925f1126f.jpg', 'Baby Bather Chair', 'baby,bather,chair', 'Bath sets\nA baby bath chair is a MUST have. Babies love the bath chair. It hugs them in with their soft mesh back support.\n\nThey know it’s time for their wash the moment you place them in. Fold the bath chair away when not used – It’s the simple.\n\niBaby F', 'Active', '2023-02-11 19:05:38', '2023-02-11 19:05:38');
