(770, 'Baby Powder Puff', 'BPP-150', 'baby-powder-puff', '<p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Features:<br>100% brand new and high quality.<br>Delicate and soft hair, easy to dry, non-deformation, refuse dust flying, let our baby get better care.<br>Suit for children and adults, especially for children in summer, hot and wet weather is easy to harm your kid’s skin.<br>You can use this puff to apply the talcum powder to your kid’s skin.<br>A big case to keep the puff can make sure the puff is clean and good to save it.<br>Also good for adult makeup tools.</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Specifications:<br>Box Material: pp (120℃)<br>Handle Material: ABS flame-retarded resin (80℃)<br>Puff Material: acrylic fibers plush<br>Color: blue, pink, Yellow<br>Size: (approx) puff* 8*5 cm, box* 9.5*7 cm</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Package Included:<br>1 PC* puff box</p><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Note:<br>1. Due to the light and screen difference, the item’s color may be slightly different from the pictures.<br>2. Please allow 0.5-2 cm differences due to manual measurement.</p>', '300', '150', '63e88aacf2bcc.jpg', 'Baby Powder Puff', 'baby,powder,puff', 'Features:\n100% brand new and high quality.\nDelicate and soft hair, easy to dry, non-deformation, refuse dust flying, let our baby get better care.\nSuit for children and adults, especially for children in summer, hot and wet weather is easy to harm your ki', 'Active', '2023-02-12 12:45:04', '2023-02-12 12:45:04'),
(771, 'Mastela Baby Rocker', 'MBR-8500', 'mastela-baby-rocker', '<p><span style=\"color: rgb(55, 65, 81); font-family: Söhne, ui-sans-serif, system-ui, -apple-system, &quot;Segoe UI&quot;, Roboto, Ubuntu, Cantarell, &quot;Noto Sans&quot;, sans-serif, &quot;Helvetica Neue&quot;, Arial, &quot;Apple Color Emoji&quot;, &quot;Segoe UI Emoji&quot;, &quot;Segoe UI Symbol&quot;, &quot;Noto Color Emoji&quot;; font-size: 16px; white-space: pre-wrap; background-color: rgb(247, 247, 248);\">Mastela Baby Rocker is a type of rocking chair designed specifically for babies. It is usually made of durable materials and has a gentle rocking motion that helps soothe and calm infants. The rocker often features a comfortable seat with a reclining option, an adjustable safety strap to keep the baby secure, and an interactive toy bar with hanging toys to entertain the baby. Some Mastela baby rockers also come with built-in music and vibration options to further soothe the baby. These features make Mastela baby rockers a popular choice for parents and caregivers as they provide a safe and comfortable place for the baby to rest, play, and relax.\n</span><br></p><ul class=\"generatedBullets\" style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Brand: Mastela</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Type: Baby Rockers</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Targeted Group: Unisex</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Are batteries needed to power the product or is this product a battery: Yes</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Is this a Dangerous Good or a Hazardous Material, Substance, or Waste that is regulated for transportation, storage, and/or disposal? : No</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Color: Multi-Color</li></ul><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Features:</strong></p><ul style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">4 easy switch positions for – play, feed, nap &amp; travel</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Single hand reclining to make a cot if baby falls asleep while playing</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">3 level adjustable vibration &amp; rocking functions soothe the baby &amp; encourage sleep</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Attractive Toy bar</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Removable as bassinet so baby can co-sleep safely on the bed with you</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">3 Point Safety Harness</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">High sides for the baby’s security removable seat pad and mattress</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Easy cleaning</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Mosquito net: yes</li></ul><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Overview:</strong></p><ul style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: