9, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\">Material: ABS</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\">Color: white and Brown</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\">Weight: 0.016kg</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif; font-size: 14px; white-space: normal; background-color: rgb(255, 255, 255);\">Suitable for babies 6 months–6 years old.</span>\n</p></li></ol><p style=\"border: 0px solid rgb(217, 217, 227); --tw-border-spacing-x:0; --tw-border-spacing-y:0; --tw-translate-x:0; --tw-translate-y:0; --tw-rotate:0; --tw-skew-x:0; --tw-skew-y:0; --tw-scale-x:1; --tw-scale-y:1; --tw-pan-x: ; --tw-pan-y: ; --tw-pinch-zoom: ; --tw-scroll-snap-strictness:proximity; --tw-ordinal: ; --tw-slashed-zero: ; --tw-numeric-figure: ; --tw-numeric-spacing: ; --tw-numeric-fraction: ; --tw-ring-inset: ; --tw-ring-offset-width:0px; --tw-ring-offset-color:#fff; --tw-ring-color:rgba(59,130,246,0.5); --tw-ring-offset-shadow:0 0 transparent; --tw-ring-shadow:0 0 transparent; --tw-shadow:0 0 transparent; --tw-shadow-colored:0 0 transparent; --tw-blu