(775, 'Snow Boots Cotton Shoes', 'SBCS-1400', 'snow-boots-cotton-shoes', '<p><span class=\"property-title\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Feature&nbsp;:&nbsp;<span class=\"property-desc line-limit-length\" title=\"ANTI-SLIPPER\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">ANTI-SLIPPER</span><br>Station&nbsp;:&nbsp;<span class=\"property-desc line-limit-length\" title=\"Winter\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Winter</span><br>High quality material&nbsp;:&nbsp;</span><span class=\"property-desc line-limit-length\" title=\"SYNTHETIC\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">SYNTHETIC<br><span class=\"property-title\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Sole material&nbsp;:&nbsp;</span><span class=\"property-desc line-limit-length\" title=\"RUBBER\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">RUBBER<br></span></span><span class=\"property-title\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Type of closure&nbsp;:&nbsp;</span><span class=\"property-desc line-limit-length\" title=\"SLIP SANDAL\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">SLIP SANDAL<br><span class=\"property-tit