(784, 'Gym Piano Mat', 'GPM-10', 'piano-mat', '<p><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Gender: Unisex</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Age Range:0 to 24 Months</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Style: Educational Toy, Electronic Toy, Musical Toy, Soft Toy, Sports Toy</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Material: Plastic</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Plastic Type: ABS</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Function: Baby toy Playmat</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Feature: Nontoxic</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Description: Baby Early Educational Mat</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Packing: Handbag box</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Product type: Baby Play Gym Playmat</span><br style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\"><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">Size: Length 29 Inch Width 19 Inch</span><br></p>', '2000', '1800', '63fdf70b7ee98.jpg', 'Baby Gym Piano Mat Toy', NULL, 'Baby Gym Piano Mat is very useful to grow babies. It makes the baby\'s muscles stable and can play independently. Can learn and listening music.', 'Active', '2023-02-28 01:06:32', '2023-12-30 18:52:14'),
(785, 'Baby Carrier Bag', 'BCB-1-0', 'baby-carrier-bag', '<div style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><b style=\"font-weight: bold;\">Description</b><strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">:</strong></div><div style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"></div><div style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">When you apply the carrier by yourself, please make sure the carrier is safe, adjust the belt length, fasten the lock, and push out the carrier from both sides by grasping it with both hands. After you ensure that it fastens completely, carry the baby with both hands, and place its legs first from upwards into the carrier. Carry the baby at the status of sitting.</div><div data-spm-anchor-id=\"a2g0o.detail.1000023.i2.5ade12d4slScsV\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">If there is anybody to help you, so please place the baby in it first and then carry it. Ask somebody to help you to fasten the lock behind you. Anyway, you cannot lose your bands until you are sure that the lock is fastened.</div><div data-spm-anchor-id=\"a2g0o.detail.1000023.i1.5ade12d4slScsV\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"></div><div style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"></div><div data-spm-anchor-id=\"a2g0o.detail.1000023.i3.5ade12d4slScsV\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><b style=\"font-weight: bold;\">Features<strong style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: bold; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">:</strong></b></div><div style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"></div><ul style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial; color: rgb(129, 131, 132);\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Breathable fabric that allows for smooth air-flow</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Greatly padded for better security</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Provides a warm environment for the child</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Two great carrying styles – chest or kangaroo style</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Adjustable buckles on the side for easy release</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">3 carrying positions – hip, back &amp;front For baby weight 7lb – 45lb</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Suitable Age: 0Months – 48Months</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Materials: Polyester</li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Colors: Red, Light Blue, Purple, Blue, Pink</li><li data-spm-anchor-id=\"a2g0o.detail.1000023.i4.5ade12d4slScsV\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Size: 30cm x 20.5cm x 24.5cm&nbsp; ( 11.81 x 8.1 x 9.7 inch)</li></ul>', '2000', '1600', '63fdbdc6054ac.jpg', 'Baby Carrier bag Backpack', 'Carrier Bag, Backpack, Baby Carrier Bag', 'A Baby Carrier bag with a backpack is the most useful and secure product. For traveling, you need safety to carry your baby and a Carrier bag will help you the way.', 'Active', '2023-02-28 14:43:25', '2023-02-28 14:43:25'),
(786, 'Flying Sensor Ball', 'FSB-1', 'flying-sensor-ball', '<div dir=\"auto\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\"><ul class=\"a-unordered-list a-vertical a-spacing-mini\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin-right: 0px; margin-bottom: 0px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; list-style-position: initial; list-style-image: initial;\"><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span class=\"a-list-item\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">High-Tech Hand-Controlled Drone Toy With Cool RGB Light: The flying orb toy provides intelligent flight. Different throwing angles and speeds will create different flight lines and boomerang effects. You can use your ingenuity to create your unique way of playing. The colorful led at night will make your magic ball cooler</span></li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span class=\"a-list-item\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Lightweight And Portable: This hover ball has undergone rigorous testing, made of high-quality materials, which are soft but durable, drop resistant, lightweight, and flexible. You don’t have to worry that the flying toy will be damaged easily by your kids. It will stop automatically when it hit the furniture or any other pieces of stuff</span></li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span class=\"a-list-item\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">USB Charging: About 20 minutes full charge, 8-10 working duration. It enables various charging options such as charging by computer, power adapter, mobile phone, portable charger, etc. The indicator light comes on when charging and goes off when fully charged. Rechargeable and can be played over and over again</span></li><li style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\"><span class=\"a-list-item\" style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Endless Pleasure And Multi-Benefits: You can play with the flying orb ball indoors and outdoors. It is a great toy for various parties and activities. Besides, it is good for developing children’s intelligence and improving their creative ability. For adults, it is a perfect way to reduce stress. It can easily bring people closer to each other. It is a perfect gift for anyone</span></li></ul><p style=\"border: 0px; font-family: inherit; font-style: inherit; font-weight: inherit; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline;\">Material: Electronic Components, Plastic</p></div><div dir=\"auto\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Product battery: 3.7V 120mAh</div><div dir=\"auto\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Charging time: 30-35mins</div><div dir=\"auto\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">Flying Time: 6-8mins</div><div dir=\"auto\" style=\"border: 0px; font-family: Poppins, sans-serif; margin: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">R/C distance: 8-10M</div>', '1000', '650', '63fdc078170b5.jpg', 'Flying Sensor Ball', 'Spinner, Spinning, Sensor, UFO Spinning ball', 'UFO Spinning Sensor ball is a very educative and learning toy. Children over 3 years can use this and learn about balance.', 'Active', '2023-02-28 14:51:33', '2023-02-28 14:51:33'),
(787, 'Music Phone Enlightenment And Learning  toys 3+', 'MP-3+', 'musicphonetoy', '<p><span style=\"color: rgb(129, 131, 132); font-family: Poppins, sans-serif;\">The best gift for babies – Funsland baby music toy is an excellent gift for babies aged six months to three years. It is not only a mobile phone toy with actual buttons, but can also be used as a teething toy, a soothing toy, an early education toy and a Montessori toy. It promotes fine motor skills in infants, encourages them to learn numbers, animals, weather, vehicles and promotes language use and development when young children imitate others on the phone. It is very suitable as a baby toy for 0-6 months, 6-12 months, 12-36 months old</span><br></p>', '800', '530', '664daaf8d0139.jpg', 'Music Phone Enlightenment And Learning 3+', '#musicphone #babymusicphone #babytoys', 'The best gift for babies – Funsland baby music toy is an excellent gift for babies aged six months to three years. It is not only a mobile phone toy with actual buttons, but can also be used as a teething toy, a soothing toy, an early education toy and a ', 'Active', '2024-05-22 21:39:46', '2024-05-22 21:39:46'),
(788, 'UNO – Classic Colour & Number Matching Card Game', 'uno-10', 'unotoys', '<h3 style=\"border: 0px; font-family: Poppins, sans-serif; font-size: 26px; font-weight: 700; margin-top: 0px; margin-bottom: 15px; outline: 0px; padding: 0px; vertical-align: baseline; clear: both; line-height: 1.3; color: rgb(61, 61, 61);\">Includes: 108 Cards and Instructions</h3><p style=\"border: 0px; font-family: Poppins, sans-serif; margin-right: 0px; margin-bottom: 20px; margin-left: 0px; outline: 0px; padding: 0px; vertical-align: baseline; color: rgb(129, 131, 132);\">UNO, the classic card game of matching colors and numbers that is easy to pick up…impossible to put down, now comes with customizable Wild Cards for added excitement. Players take turns racing to get rid of all their cards by matching a card in their hand with the current card shown on top of the deck. Special Action cards deliver game-changing moments and help defeat opponents. Use the Swap Hands card to change hands with any other opponent and use the 3 customizable (and erasable) Wild Cards to write your own rules. You’ll find 19 cards of each color (red, green, blue, and yellow), plus 8 Draw Two, Reverse, and Skip cards in every color, along with 4 Wild Cards, 4 Wild Draw Four cards, 1 Wild Swap Hands Card and 3 Wild Customizable cards. If you can’t make a match, you must draw from the central pile! Don’t forget to shout “UNO” when you only have one card remaining! The player to gets rid of all the cards in their hand scores points for any cards their opponents are left holding. The first player to reach 500 points wins. Get Wild 4 UNO. includes 112 cards and instructions. Colors and decorations may vary.</p>', '250', '120', '664db7928b9ed.jpg', 'UNO – Classic Colour & Number Matching Card Game', '#babyUno #Uno', 'UNO, the classic card game of matching colors and numbers that is easy to pick up…impossible to put down, now comes with customizable Wild Cards for added excitement. Players take turns racing to get rid of all their cards by matching a card in their hand', 'Active', '2024-05-22 22:17:30', '2024-05-22 22:17:30'),
